import{_ as a,c as t,o,a2 as r}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1780541175000}'),i={name:"guide/privacy.md"};function s(n,e,l,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>Gomoku is designed as an offline-first application. This page explains what (if any) data the app collects and how it is used.</p><h2 id="local-first-design" tabindex="-1">Local-first design <a class="header-anchor" href="#local-first-design" aria-label="Permalink to &quot;Local-first design&quot;">​</a></h2><ul><li>Game records (saved replays / SGF files), settings, and logs are stored locally on your Mac. They are not uploaded by default.</li><li>LAN play transmits moves and room metadata only to peers on your local network while a match is in progress.</li></ul><h2 id="what-we-do-not-collect" tabindex="-1">What we do not collect <a class="header-anchor" href="#what-we-do-not-collect" aria-label="Permalink to &quot;What we do not collect&quot;">​</a></h2><ul><li>We do not collect personal files, images, or browsing history.</li><li>We do not send your game records or private data to external servers unless you explicitly use a cloud or sharing feature that performs an upload (not enabled by default).</li></ul><h2 id="permissions-used-by-the-app" tabindex="-1">Permissions used by the app <a class="header-anchor" href="#permissions-used-by-the-app" aria-label="Permalink to &quot;Permissions used by the app&quot;">​</a></h2><ul><li><strong>Local Network</strong>: Required to discover and join LAN games on your Wi‑Fi network. You will be prompted by macOS the first time this is needed.</li><li><strong>Files and Folders</strong>: Required to read/open and save game records (SGF) and user settings.</li><li><strong>Screen Recording / Accessibility</strong>: Optional; only requested if you enable auxiliary features that require them.</li></ul><p>You can manage these permissions in <strong>System Settings → Privacy &amp; Security</strong>.</p><h2 id="third-party-services" tabindex="-1">Third-party services <a class="header-anchor" href="#third-party-services" aria-label="Permalink to &quot;Third-party services&quot;">​</a></h2><p>Gomoku does not include third-party analytics or advertising by default. If the project adds optional cloud or sharing integrations in the future, they will be documented and disclosed here.</p><h2 id="privacy-requests" tabindex="-1">Privacy requests <a class="header-anchor" href="#privacy-requests" aria-label="Permalink to &quot;Privacy requests&quot;">​</a></h2><p>If you believe Gomoku holds personal data about you and wish to request access, deletion, or portability, please open an issue in the project repository or contact the maintainers. Typical responses will confirm whether any personal data is held and how to remove it.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy questions or requests, open an issue at the project repository (<a href="https://github.com/gomoku-app/gomoku-site" target="_blank" rel="noreferrer">https://github.com/gomoku-app/gomoku-site</a>) or contact the maintainers.</p>',15)])])}const y=a(i,[["render",s]]);export{u as __pageData,y as default};
